    return out

def transform(grid):
    out=[r[:] for r in grid]; pts=[(r,c) for r in range(len(grid)) for c in range(len(grid[0])) if grid[r][c]]
    if pts:
        rs=[p[0] for p in pts]; cs=[p[1] for p in pts]; out[(min(rs)+max(rs))//2][(min(cs)+max(cs))//2]=1
    return out
